contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint selfBalBefore = address(this).balance;

        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = address(c).balance;
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint selfBalAfter = address(this).balance;

        assert(
            (balBefore >= value && !reverted && balAfter == balBefore - value && selfBalAfter == selfBalBefore + value && depositsAfter == depositsBefore) ||
            (balBefore < value && reverted && balAfter == balBefore && selfBalAfter == selfBalBefore && depositsAfter == depositsBefore)
        );
    }
}

